function LP(u, v) { return [LO.x + u * SU, LO.y - v * SV]; }
var RO = { x: 560, y: 500 }, SS = 55;               // xy-plane panel
function RP(x, y) { return [RO.x + x * SS, RO.y - y * SS]; }

/* ── state ──────────────────────────────────────────────────────── */
var u0 = 1.8, du = 2.0, v0 = 0.35, dv = 0.65;
var fx = compileExpr('u*cos(v)', ['u', 'v']);
var fy = compileExpr('u*sin(v)', ['u', 'v']);
var BLUE = '#27a2dd', FILL = '#b7dcf2';

function mtext(str, x, y, o) {
  o = o || {};
  var t = draw.text(str).font({
    family: 'Times New Roman, serif', style: 'italic',
    size: o.size || 18, anchor: o.anchor || 'middle'
  }).move(x, y).fill(o.color || '#222');
  if (o.halo !== false) t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3, 'stroke-linejoin': 'round' });
  return t;
}
function fmt(x) {
  if (!isFinite(x)) return '—';
  var a = Math.abs(x);
  if (a >= 1000 || (a > 0 && a < 0.001)) return x.toPrecision(3);
  return String(Math.round(x * 100) / 100);
}

/* ── axes with arrowheads ───────────────────────────────────────── */
var mk = draw.marker(12, 12, function (add) { add.path('M1,1 L11,6 L1,11 z').fill('#333'); }).ref(11, 6);
draw.line(15, 515, 358, 515).stroke({ color: '#333', width: 2 }).marker('end', mk);
draw.line(45, 540, 45, 20).stroke({ color: '#333', width: 2 }).marker('end', mk);
mtext('u', 346, 496, { size: 20 });
mtext('v', 60, 34, { size: 20 });
draw.line(528, 500, 893, 500).stroke({ color: '#333', width: 2 }).marker('end', mk);
draw.line(560, 528, 560, 16).stroke({ color: '#333', width: 2 }).marker('end', mk);
mtext('x', 882, 480, { size: 20 });
mtext('y', 576, 30, { size: 20 });

/* ── transformation arrow between panels ────────────────────────── */
var arrow = draw.path('M378 318 C416 270 452 262 486 276 L486 252 L524 306 L484 358 L484 332 C452 346 414 340 378 318 Z')
  .fill('#fdeed3').stroke({ color: '#b9b9b9', width: 2 });
arrow.css('cursor', 'pointer');
arrow.on('mousemove', function (e) { showTooltip('T: (u,v) ↦ (x(u,v), y(u,v))', e); })
  .on('mouseleave', hideTooltip)
  .on('click', function () {
    showPopup('The transformation T', 'T carries every point (u,v) of S to the point (x(u,v), y(u,v)) of the xy-plane. Grid lines u = const and v = const become the curved boundaries of the image region R.');
  });

/* ── right-panel clipped group for the image ────────────────────── */
var clip = draw.clip(); clip.rect(525, 6, 368, 518);
var rg = draw.group(); rg.clipWith(clip);
var rFill = rg.path('').fill(FILL).attr('fill-opacity', 0.75);
var cU0 = rg.path('').fill('none').stroke({ color: BLUE, width: 3, 'stroke-linecap': 'round' });
var cU1 = rg.path('').fill('none').stroke({ color: BLUE, width: 3, 'stroke-linecap': 'round' });
var cV0 = rg.path('').fill('none').stroke({ color: BLUE, width: 3, 'stroke-linecap': 'round' });
var cV1 = rg.path('').fill('none').stroke({ color: BLUE, width: 3, 'stroke-linecap': 'round' });
rFill.css('cursor', 'pointer');
rFill.on('mousemove', function (e) { showTooltip('R = T(S): the curved image of rectangle S', e); })
  .on('mouseleave', hideTooltip)
  .on('click', function () {
    showPopup('Area scaling and the Jacobian', 'area(S) = Δu·Δv, while area(R) ≈ |∂(x,y)/∂(u,v)|·Δu·Δv for small Δu, Δv. Compare the readouts: area(R)/area(S) is the average stretch over S; |J| at the center is the pointwise stretch.');
  });

/* image curve labels (drawn outside the clip) */
var lblUU0 = mtext('Image of u = u₀', 0, 0, { size: 15, anchor: 'end' });
var lblUU1 = mtext('Image of u = u₀ + Δu', 0, 0, { size: 15, anchor: 'end' });
var lblVV0 = mtext('Image of v = v₀', 0, 0, { size: 15, anchor: 'middle' });
var lblVV1 = mtext('Image of v = v₀ + Δv', 0, 0, { size: 15, anchor: 'start' });
var lblR = mtext('R', 0, 0, { size: 22 });

/* area readouts */
var areaSTxt = draw.text('').font({ family: 'sans-serif', size: 13 }).fill('#444').move(45, 548);
var areaRTxt = draw.text('').font({ family: 'sans-serif', size: 13 }).fill('#444').move(560, 534);
var areaJTxt = draw.text('').font({ family: 'sans-serif', size: 13 }).fill('#444').move(560, 550);

/* ── left panel: rectangle S, grid lines, dots, labels ──────────── */
var rectS = draw.rect().fill(FILL).attr('fill-opacity', 0.7).stroke({ color: BLUE, width: 2 });
var gV0 = draw.line(0, 0, 0, 0).stroke({ color: BLUE, width: 3 });
var gV1 = draw.line(0, 0, 0, 0).stroke({ color: BLUE, width: 3 });
var gH0 = draw.line(0, 0, 0, 0).stroke({ color: BLUE, width: 3 });
var gH1 = draw.line(0, 0, 0, 0).stroke({ color: BLUE, width: 3 });
rectS.css('cursor', 'pointer');
rectS.on('mousemove', function (e) { showTooltip('S: u₀ ≤ u ≤ u₀+Δu,  v₀ ≤ v ≤ v₀+Δv', e); })
  .on('mouseleave', hideTooltip)
  .on('click', function () {
    showPopup('The rectangle S', 'S is the small axis-aligned rectangle in the uv-plane. Its sides lie on u = u₀, u = u₀+Δu, v = v₀, v = v₀+Δv, and each side is carried by T to one boundary curve of R.');
  });

var dots = [];
(function () {
  for (var i = 0; i < 4; i++) {
    var c = draw.circle(13).fill(BLUE).stroke({ color: '#fff', width: 1.5 });
    c.css('cursor', 'grab');
    c.node.style.touchAction = 'none';
    c.on('mousemove', function (e) { showTooltip('Drag to move or resize S — the image R follows', e); })
      .on('mouseleave', hideTooltip);
    dots.push(c);
  }
})();

var tU0 = mtext('u = u₀', 0, 0, { size: 18 });
var tU1 = mtext('u = u₀ + Δu', 0, 0, { size: 18 });
var tV0 = mtext('v = v₀', 0, 0, { size: 17, anchor: 'start' });
var tV1 = mtext('v = v₀ + Δv', 0, 0, { size: 17, anchor: 'start' });
var tP00 = mtext('(u₀, v₀)', 0, 0, { size: 15, anchor: 'end' });
var tDu = mtext('Δu', 0, 0, { size: 17 });
var tDv = mtext('Δv', 0, 0, { size: 17, anchor: 'start' });
var tS = mtext('S', 0, 0, { size: 22 });

/* ── sampling of the image under T ──────────────────────────────── */
function evalT(u, v) {
  var X, Y;
  try { X = fx(u, v); Y = fy(u, v); } catch (e) { return null; }
  return (isFinite(X) && isFinite(Y)) ? [X, Y] : null;
}
function sampU(u, va, vb, n) { var p = []; for (var i = 0; i < n; i++) p.push(evalT(u, va + (vb - va) * i / (n - 1))); return p; }
function sampV(v, ua, ub, n) { var p = []; for (var i = 0; i < n; i++) p.push(evalT(ua + (ub - ua) * i / (n - 1), v)); return p; }
function setCurve(el, pts) {
  var d = '', pen = false;
  for (var i = 0; i < pts.length; i++) {
    var p = pts[i];
    if (!p) { pen = false; continue; }
    var s = RP(p[0], p[1]);
    d += (pen ? 'L' : 'M') + s[0].toFixed(1) + ' ' + s[1].toFixed(1);
    pen = true;
  }
  el.attr('d', d);
}
function lastFinite(pts) { for (var i = pts.length - 1; i >= 0; i--) if (pts[i]) return pts[i]; return null; }
function placeLbl(el, p, dx, dy) {
  if (!p) { el.attr('display', 'none'); return; }
  var s = RP(p[0], p[1]);
  el.attr({ display: '', x: s[0] + dx, y: s[1] + dy });
}
function polyArea(pts) {
  var a = 0, n = pts.length;
  for (var i = 0; i < n; i++) { var j = (i + 1) % n; a += pts[i][0] * pts[j][1] - pts[j][0] * pts[i][1]; }
  return Math.abs(a / 2);
}

/* ── redraw ─────────────────────────────────────────────────────── */
function redrawRight() {
  var U1 = u0 + du, V1 = v0 + dv;
  var bnd = sampV(v0, u0, U1, 26).concat(sampU(U1, v0, V1, 26),
    sampV(V1, U1, u0, 26), sampU(u0, V1, v0, 26)).filter(Boolean);
  var d = '';
  for (var i = 0; i < bnd.length; i++) {
    var s = RP(bnd[i][0], bnd[i][1]);
    d += (i ? 'L' : 'M') + s[0].toFixed(1) + ' ' + s[1].toFixed(1);
  }
  rFill.attr('d', d ? d + 'Z' : '');

  var eu = 0.35 * du, ev = 0.35 * dv;
  var cU0p = sampU(u0, v0 - ev, V1 + ev, 44);
  var cU1p = sampU(U1, v0 - ev, V1 + ev, 44);
  var cV0p = sampV(v0, u0 - eu, U1 + eu, 44);
  var cV1p = sampV(V1, u0 - eu, U1 + eu, 44);
  setCurve(cU0, cU0p); setCurve(cU1, cU1p); setCurve(cV0, cV0p); setCurve(cV1, cV1p);

  placeLbl(lblUU0, lastFinite(cU0p), -8, -9);
  placeLbl(lblUU1, lastFinite(cU1p), -8, -13);
  placeLbl(lblVV1, lastFinite(cV1p), 8, 17);
  placeLbl(lblVV0, lastFinite(cV0p), -12, 33);

  var uc = u0 + du / 2, vc = v0 + dv / 2, c0 = evalT(uc, vc);
  if (c0) { var sc = RP(c0[0], c0[1]); lblR.attr({ display: '', x: sc[0], y: sc[1] + 8 }); }
  else lblR.attr('display', 'none');

  var areaS = du * dv, areaR = polyArea(bnd);
  areaSTxt.text('area(S) = Δu·Δv = ' + fmt(areaS) + ' (uv-units²)');
  areaRTxt.text('area(R) ≈ ' + fmt(areaR) + ' (xy-units²)');
  var h = 1e-3, J = NaN;
  try {
    var xu = (fx(uc + h, vc) - fx(uc - h, vc)) / (2 * h);
    var xv = (fx(uc, vc + h) - fx(uc, vc - h)) / (2 * h);
    var yu = (fy(uc + h, vc) - fy(uc - h, vc)) / (2 * h);
    var yv = (fy(uc, vc + h) - fy(uc, vc - h)) / (2 * h);
    J = xu * yv - xv * yu;
  } catch (e) { J = NaN; }
  areaJTxt.text('area(R)/area(S) ≈ ' + fmt(areaR / areaS) + '    |∂(x,y)/∂(u,v)| at center ≈ ' + fmt(Math.abs(J)));
}

function redrawLeft() {
  var U1 = u0 + du, V1 = v0 + dv;
  var p00 = LP(u0, v0), p10 = LP(U1, v0), p11 = LP(U1, V1), p01 = LP(u0, V1);
  rectS.attr({ x: p01[0], y: p01[1], width: p10[0] - p00[0], height: p00[1] - p01[1] });
  gV0.plot(p01[0], p01[1] - 58, p00[0], p00[1] + 52);
  gV1.plot(p11[0], p11[1] - 58, p10[0], p10[1] + 52);
  gH0.plot(p00[0] - 48, p00[1], p10[0] + 30, p10[1]);
  gH1.plot(p01[0] - 48, p01[1], p11[0] + 30, p11[1]);
  dots[0].center(p00[0], p00[1]);
  dots[1].center(p10[0], p10[1]);
  dots[2].center(p11[0], p11[1]);
  dots[3].center(p01[0], p01[1]);
  tU0.attr({ x: p01[0], y: p01[1] - 66 });
  tU1.attr({ x: p11[0], y: p11[1] - 66 });
  tV0.attr({ x: p10[0] + 38, y: p10[1] - 5 });
  tV1.attr({ x: p11[0] + 38, y: p11[1] - 5 });
  tP00.attr({ x: p00[0] - 8, y: p00[1] + 30 });
  tDu.attr({ x: (p00[0] + p10[0]) / 2, y: p00[1] + 44 });
  tDv.attr({ x: p10[0] + 13, y: (p00[1] + p01[1]) / 2 + 6 });
  tS.attr({ x: (p00[0] + p10[0]) / 2, y: (p00[1] + p01[1]) / 2 + 8 });
  redrawRight();
}

/* ── corner dragging ────────────────────────────────────────────── */
var dragIdx = -1;
dots.forEach(function (c, i) {
  c.on('pointerdown', function (e) { dragIdx = i; c.css('cursor', 'grabbing'); e.preventDefault(); });
});
function toVB(e) {
  var r = draw.node.getBoundingClientRect();
  return [(e.clientX - r.left) * 900 / r.width, (e.clientY - r.top) * 560 / r.height];
}
window.addEventListener('pointermove', function (e) {
  if (dragIdx < 0) return;
  var pt = toVB(e);
  var u = Math.min(6.85, Math.max(0.15, (pt[0] - LO.x) / SU));
  var v = Math.min(2.3, Math.max(0.06, (LO.y - pt[1]) / SV));
  var g = 0.12, U1 = u0 + du, V1 = v0 + dv;
  if (dragIdx === 0) { u0 = Math.min(u, U1 - g); du = U1 - u0; v0 = Math.min(v, V1 - g); dv = V1 - v0; }
  else if (dragIdx === 1) { du = Math.max(u, u0 + g) - u0; v0 = Math.min(v, V1 - g); dv = V1 - v0; }
  else if (dragIdx === 2) { du = Math.max(u, u0 + g) - u0; dv = Math.max(v, v0 + g) - v0; }
  else { u0 = Math.min(u, U1 - g); du = U1 - u0; dv = Math.max(v, v0 + g) - v0; }
  redrawLeft();
});
window.addEventListener('pointerup', function () {
  if (dragIdx >= 0) { dots[dragIdx].css('cursor', 'grab'); dragIdx = -1; }
});

/* ── equation inputs (scaffold owns parsing + inline errors) ────── */
bindEquationInput('xuvInput', function (fn) { fx = fn; redrawRight(); }, { variables: ['u', 'v'] });
bindEquationInput('yuvInput', function (fn) { fy = fn; redrawRight(); }, { variables: ['u', 'v'] });

/* ── demo step player ───────────────────────────────────────────── */
var steps = [
  { t: 'A rectangle and its curved image', n: 'The rectangle S, bounded by u = u₀, u = u₀+Δu and v = v₀, v = v₀+Δv, is carried by T to the curved region R. Each side of S becomes one labeled boundary curve of R.' },
  { t: 'Move the rectangle', n: 'Drag a corner of S: as (u₀, v₀), Δu and Δv change, R deforms continuously. A same-size rectangle maps to a larger area farther from the origin — previewing the Jacobian\u2019s area-scaling role.' },
  { t: 'Change the transformation', n: 'Edit x(u,v) or y(u,v) — try x = u^2 or x = u + v. S stays fixed while R redraws into a new shape: the mapping formulas, not the rectangle, control the distortion.' }
];
var curStep = 0;
function showStep(i) {
  curStep = i;
  document.getElementById('demoNarration').textContent = (i + 1) + '. ' + steps[i].t + ' — ' + steps[i].n;
  document.getElementById('stepLabel').textContent = (i + 1) + ' / ' + steps.length;
  dots.forEach(function (c) { c.stroke({ color: i === 1 ? '#e07b00' : '#fff', width: i === 1 ? 2.5 : 1.5 }); });
  ['xuvInput', 'yuvInput'].forEach(function (id) {
    var inp = document.getElementById(id);
    if (inp) inp.style.border = (i === 2) ? '2px solid #27a2dd' : '1px solid #aaa';
  });
}
function nextStep() { showStep(Math.min(steps.length - 1, curStep + 1)); }
function prevStep() { showStep(Math.max(0, curStep - 1)); }

/* ── initial draw ───────────────────────────────────────────────── */
redrawLeft();
showStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: A change of variables T: (u,v) → (x(u,v), y(u,v)) maps an axis-aligned rectangle S in the uv-plane to a curved region R in the xy-plane, and the Jacobian determinant ∂(x,y)/∂(u,v) measures the local area-stretch factor of that mapping.
KEY INSIGHT (what students should walk away understanding): The transformation formulas alone determine how a small rectangle in the uv-plane is stretched into its curved image, and the Jacobian determinant ∂(x,y)/∂(u,v) is precisely the factor by which area is scaled at each point.
DEMO STEPS: 3 guided steps — implement the step player in #ui

FULL BLUEPRINT:
{
  "concept": "A change of variables T: (u,v) → (x(u,v), y(u,v)) maps an axis-aligned rectangle S in the uv-plane to a curved region R in the xy-plane, and the Jacobian determinant ∂(x,y)/∂(u,v) measures the local area-stretch factor of that mapping.",
  "figureType": "diagram",
  "elements": [
    "uv-plane axes with horizontal axis labeled u and vertical axis labeled v",
    "rectangular region S, shaded light blue, bounded by vertical lines u = u0 and u = u0 + Δu and horizontal lines v = v0 and v = v0 + Δv",
    "four draggable corner dots of S, with corner (u0, v0) labeled",
    "side-length labels Δu (below the rectangle) and Δv (right of the rectangle)",
    "boundary line labels: u = u0, u = u0 + Δu, v = v0, v = v0 + Δv",
    "large curved transformation arrow between the two panels",
    "xy-plane axes with horizontal axis labeled x and vertical axis labeled y",
    "curved image region R, shaded light blue, a distorted parallelogram bounded by four blue curves",
    "image curve labels: Image of u = u0, Image of u = u0 + Δu, Image of v = v0, Image of v = v0 + Δv",
    "area readout annotations for area(S) and area(R)"
  ],
  "interactions": [
    {
      "id": "transformEquations",
      "type": "equation_input",
      "label": "Transformation equations",
      "fields": [
        {
          "id": "xuv",
          "label": "x(u,v) =",
          "default": "u*cos(v)",
          "variables": [
            "u",
            "v"
          ],
          "domain": [
            0,
            6
          ],
          "role": "transformation x-component"
        },
        {
          "id": "yuv",
          "label": "y(u,v) =",
          "default": "u*sin(v)",
          "variables": [
            "u",
            "v"
          ],
          "domain": [
            0,
            6
          ],
          "role": "transformation y-component"
        }
      ],
      "teaches": "The shape and area of R are entirely determined by the formulas x(u,v) and y(u,v) — editing either one redraws the curved image, and the local stretching is exactly what the Jacobian determinant ∂(x,y)/∂(u,v) quantifies at each point"
    },
    {
      "id": "dragRectangle",
      "type": "drag",
      "teaches": "Moving or resizing S by dragging its corners deforms R correspondingly, showing that each boundary line of S maps to one specific bounding curve of R and that the same rectangle can map to very different areas depending on where it sits in the uv-plane"
    }
  ],
  "demo_steps": [
    {
      "title": "A rectangle and its curved image",
      "narration": "The rectangle S in the uv-plane, bounded by u = u0, u = u0 + Δu and v = v0, v = v0 + Δv, is carried by the transformation T to the curved region R in the xy-plane. Each side of S becomes one labeled boundary curve of R.",
      "state": {}
    },
    {
      "title": "Move the rectangle",
      "narration": "Drag a corner of S: as Δu and Δv change, or as the rectangle shifts to a new (u0, v0), the image R deforms continuously — notice how the same-size rectangle maps to a larger area farther from the origin, previewing the area-scaling role of the Jacobian.",
      "state": {}
    },
    {
      "title": "Change the transformation",
      "narration": "Edit x(u,v) or y(u,v) — try x = u^2 or swapping in x = u + v. The rectangle S stays fixed while R redraws into a completely new shape, showing that the mapping formulas, not the rectangle, control the distortion.",
      "state": {}
    }
  ],
  "keyInsight": "The transformation formulas alone determine how a small rectangle in the uv-plane is stretched into its curved image, and the Jacobian determinant ∂(x,y)/∂(u,v) is precisely the factor by which area is scaled at each point.",
  "reconstructionNotes": "Two side-by-side panels matching the textbook figure: uv-plane on the left with a small light-blue rectangle S in the first quadrant, blue gridline extensions through its sides, labeled Δu and Δv, corner (u0, v0) marked; a large pale curved arrow in the middle pointing right; xy-plane on the right with the light-blue curved quadrilateral R whose four bounding curves extend slightly past the region and are labeled as the images of the four rectangle sides. Keep both panels to the same visual scale. Corner dots of S should look grabbable. Recompute R by sampling the boundary curves through the current x(u,v), y(u,v); show a small area(S) vs area(R) readout so the area-stretch relationship is visible even before the Jacobian is introduced. Parse errors in the equation fields should be flagged inline and leave the last valid image in place."
}

