/* ── sampling of the image under T ──────────────────────────────── */
function evalT(u, v) {
  var X, Y;
  try { X = fx(u, v); Y = fy(u, v); } catch (e) { return null; }
  return (isFinite(X) && isFinite(Y)) ? [X, Y] : null;
}
function sampU(u, va, vb, n) { var p = []; for (var i = 0; i < n; i++) p.push(evalT(u, va + (vb - va) * i / (n - 1))); return p; }
function sampV(v, ua, ub, n) { var p = []; for (var i = 0; i < n; i++) p.push(evalT(ua + (ub - ua) * i / (n - 1), v)); return p; }
/* clamp world coords so a wild expression cannot fling paths off-canvas */
function clampW(p) {
  return [Math.max(RO.x - 20, Math.min(888, p[0])), Math.max(8, Math.min(528, p[1]))];
}
function setCurve(el, pts) {
  var d = '', pen = false;
  for (var i = 0; i < pts.length; i++) {
    var p = pts[i];
    if (!p) { pen = false; continue; }
    var s = clampW(RP(p[0], p[1]));
    d += (pen ? 'L' : 'M') + s[0].toFixed(1) + ' ' + s[1].toFixed(1) + ' ';
    pen = true;
  }
  if (!d) d = 'M-100 -100';   // park an empty curve off-canvas, never ''
  el.attr('d', d);
}
function firstFinite(pts) { for (var i = 0; i < pts.length; i++) if (pts[i]) return pts[i]; return null; }
function lastFinite(pts) { for (var i = pts.length - 1; i >= 0; i--) if (pts[i]) return pts[i]; return null; }
/* Place a label near a curve endpoint, keeping the whole text box on-canvas:
   'start'/'middle' anchors flip to 'end' when the anchor point is near the
   right edge, and the anchor point itself is clamped to safe margins. */
function placeLbl(el, p, dx, dy) {
  if (!p) { el.attr('display', 'none'); return; }
  var s = clampW(RP(p[0], p[1]));
  var x = s[0] + dx, y = s[1] + dy;
  var anchor = el.attr('text-anchor') || 'middle';
  if ((anchor === 'start' || anchor === 'middle') && x > 730) {
    anchor = 'end';
    x = Math.min(x, s[0] - 10);
  }
  x = Math.max(368, Math.min(886, x));
  y = Math.max(14, Math.min(524, y));
  el.attr({ display: '', 'text-anchor': anchor, x: x, y: y });
}
function polyArea(pts) {
  var a = 0, n = pts.length;
  for (var i = 0; i < n; i++) { var j = (i + 1) % n; a += pts[i][0] * pts[j][1] - pts[j][0] * pts[i][1]; }
  return Math.abs(a / 2);
}

